#include <string>
#include <algorithm>

using namespace std;

int main() {
    string wordToCount; // Wort, das gezählt werden soll
    int count = 0; // Anzahl der Vorkommen

    // Eingabe des Wortes, das gezählt werden soll
    cout << "Geben Sie das Wort ein, das gezählt werden soll: ";
    cin >> wordToCount;
    transform(wordToCount.begin(), wordToCount.end(), wordToCount.begin(), ::tolower); // Umwandlung in Kleinbuchstaben

    string fileName; // Name der Textdatei
    cout << "Geben Sie den Dateinamen ein: ";
    cin >> fileName;

    ifstream file(fileName); // Öffnen der Textdatei

    if (!file.is_open()) { // Prüfen, ob die Datei erfolgreich geöffnet wurde
        cerr << "Fehler: Datei konnte nicht geöffnet werden." << endl;
        return 1;
    }

    string line; // Variablen für Zeilenlesbarkeit
    while (getline(file, line)) { // Zeilenweise Lesen der Textdatei
        transform(line.begin(), line.end(), line.begin(), ::tolower); // Umwandlung in Kleinbuchstaben
        size_t pos = std::string::npos; // Standardwert für die Position des Suchstrings
        while ((pos = line.find(wordToCount, pos)) != std::string::npos) { // Suchen nach dem Wort in der aktuellen Zeile
            count++; // Zähler erhöhen
            pos += wordToCount.length(); // Springen zum nächsten Vorkommen
        }
    }

    file.close(); // Schließen der Textdatei

